"use client";

import { useMemo, useState } from "react";

export function DotRevealGrid() {
  const [active, setActive] = useState(false);

  const dots = useMemo(
    () =>
      Array.from({ length: 48 }, (_, index) => {
        const col = index % 12;
        const row = Math.floor(index / 12);
        const x = col - 5.5;
        const y = row - 1.5;

        return (
          <span
            key={index}
            className="landing-dot-matrix-dot"
            style={{
              ["--dot-x" as string]: x.toString(),
              ["--dot-y" as string]: y.toString(),
            }}
          />
        );
      }),
    [],
  );

  return (
    <button
      type="button"
      className="landing-dot-reveal-group absolute bottom-11 right-8 z-20 sm:bottom-14 sm:right-16"
      aria-label="Reveal self-healing software message"
      data-active={active ? "true" : "false"}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      onFocus={() => setActive(true)}
      onBlur={() => setActive(false)}
      onClick={() => setActive((current) => !current)}
    >
      <div className="landing-dot-reveal-content">
        <span className="landing-dot-reveal-title">SELF-HEALING SOFTWARE</span>
        <span className="landing-dot-reveal-pulse" aria-hidden="true" />
      </div>
      <div className="landing-dot-reveal-grid" aria-hidden="true">
        {dots}
      </div>
    </button>
  );
}
